-- RID=52 | MENU=3 | ITEM=1 | RQUERY=1 | NAME=Daftar Permintaan Pembelian (PR) | FILE=ListPurchaseRequest
SELECT pr.prnotransaksi, pr.prtgl, kd.knama as diminta, km.knama AS mintake, pr.prtgldipakai, st.nama AS progress , pr.prmatauang , pr.prkurs , pr.prdiskonpersen , pr.prjmldiskon, pr.prbiayalain , pr.prtotalpajak1detail, pr.prtotalpajak2detail, prd.namabarang, b.bkode, prd.catatan, prd.jml, prd.satuan, prd.diskon, prd.harga AS hargajual, ((prd.harga * prd.jml) - prd.jmldiskon)AS total , pr.prtotaltransaksi FROM m4_pr pr JOIN m4_pr_detail prd ON pr.prid = prd.idpr JOIN m0_status st ON pr.prstatus = st.kode JOIN m1_item b ON prd.idbarang = b.bid JOIN m1_contact kd ON pr.prdimintaoleh = kd.kid LEFT JOIN m1_contact km ON pr.prmintake = km.kid ORDER BY pr.prtgl, pr.prnotransaksi, prd.urutan;

-- RID=276 | MENU=3 | ITEM=2 | RQUERY=1 | NAME=Daftar Permintaan Pembelian (PR) Outstanding | FILE=PROutstanding
SELECT pr.prnotransaksi , pr.prtgl, ks.knama AS prmintake , kc.knama AS prdimintaoleh , pr.prcatatan , st.nama AS prstatus , b.bkode , prd.namabarang , prd.catatan , prd.jml , prd.satuan , (prd.jmlrealisasi / prd.nilaisatuan) AS jmlrealisasi , (prd.jml - (prd.jmlrealisasi / prd.nilaisatuan)) AS sisa FROM m4_pr pr JOIN m4_pr_detail prd ON pr.prid = prd.idpr JOIN m1_item b ON prd.idbarang = b.bid JOIN m1_contact kc ON pr.prdimintaoleh = kc.kid JOIN m0_status st ON pr.prstatus = st.kode LEFT JOIN m1_contact ks ON pr.prmintake = ks.kid ORDER BY pr.prtgl, pr.prnotransaksi, prd.urutan;

-- RID=295 | MENU=3 | ITEM=3 | RQUERY=1 | NAME=Permintaan Pembelian (PR)  | FILE=PurchaseRequestDetail_new
SELECT kd.knama AS prdimintaoleh , pr.prtgldipakai, pr.prtgl, pr.prnotransaksi, pr.prmatauang, pr.prkurs, pr.pruraian , st.nama AS prstatus , prd.catatan, prd.urutan, b.bkode, prd.namabarang, sum(prd.jml) as jml, prd.satuan, prd.diskon, prd.harga , ((SUM(prd.jml) * prd.harga) - prd.jmldiskon) as total , pr.prdiskonpersen, pr.prjmldiskon , pr.prtotalpajak1detail, pr.prtotalpajak2detail, pr.prbiayalain FROM m4_pr pr JOIN m4_pr_detail prd ON pr.prid = prd.idpr JOIN m1_item b ON prd.idbarang = b.bid JOIN m1_contact kd ON pr.prdimintaoleh = kd.kid JOIN m0_status st ON pr.prstatus = st.kode GROUP BY pr.prnotransaksi, b.bkode, prd.namabarang, prd.tipebarang, prd.satuan, prd.harga, prd.diskon ORDER BY pr.prtgl, pr.prid , pr.prnotransaksi, prd.urutan;

-- RID=510 | MENU=3 | ITEM=4 | RQUERY=1 | NAME=PERMINTAAN PEMBELIAN | FILE=PurchaseRequestDetail2
SELECT kd.knama AS prdimintaoleh , pr.prtgldipakai, pr.prtgl, pr.prnotransaksi, pr.prmatauang, pr.prkurs, pr.pruraian , st.nama AS prstatus , prd.urutan, b.bkode, prd.namabarang, sum(prd.jml) as jml, prd.satuan, prd.diskon, prd.harga , ((SUM(prd.jml) * prd.harga) - prd.jmldiskon) as total , pr.prdiskonpersen, pr.prjmldiskon , pr.prtotalpajak1detail, pr.prtotalpajak2detail, pr.prbiayalain , pr.prtotaltransaksi , b.bstok , b.bstokminimal , b.bstokmaksimal , prd.catatan, b.bhargabeli , user1.unama as poinputuser , pr.prinputtgl , user2.unama AS pomodifikasiuser , pr.prmodifikasitgl, pr.prstatus AS statusc, st.nama as prstatunama FROM m4_pr pr JOIN m4_pr_detail prd ON pr.prid = prd.idpr JOIN m1_item b ON prd.idbarang = b.bid JOIN m1_contact kd ON pr.prdimintaoleh = kd.kid JOIN m0_status st ON pr.prstatus = st.kode LEFT JOIN m0_user user1 on pr.prinputuser= user1.userid LEFT JOIN m0_user user2 on pr.prmodifikasiuser = user2.userid GROUP BY pr.prnotransaksi, b.bkode, prd.namabarang, prd.tipebarang, prd.satuan, prd.harga, prd.diskon ORDER BY pr.prtgl, pr.prid , pr.prnotransaksi, prd.urutan;

