-- RID=1634 | MENU=3 | ITEM=14 | RQUERY=1 | NAME=Daftar Permintaan Pembelian (PR) | FILE=ListPurchaseRequest2
SELECT pr.prnotransaksi, pr.prtgl, kd.knama as diminta, km.knama AS mintake, pr.prtgldipakai, st.nama AS progress , pr.prmatauang , pr.prkurs , pr.prdiskonpersen , pr.prjmldiskon, pr.prbiayalain , pr.prtotalpajak1detail, pr.prtotalpajak2detail, prd.namabarang, b.bkode, prd.catatan, prd.jml, prd.satuan, prd.diskon, prd.harga AS hargajual, ((prd.harga * prd.jml) - prd.jmldiskon)AS total , pr.prtotaltransaksi FROM m4_pr pr JOIN m4_pr_detail prd ON pr.prid = prd.idpr JOIN m0_status st ON pr.prstatus = st.kode JOIN m1_item b ON prd.idbarang = b.bid JOIN m1_contact kd ON pr.prdimintaoleh = kd.kid LEFT JOIN m1_contact km ON pr.prmintake = km.kid ORDER BY pr.prtgl, pr.prnotransaksi, prd.urutan;

-- RID=50001635 | MENU=3 | ITEM=15 | RQUERY=1 | NAME=Purchase Requisition History  | FILE=PR HISTORY KAWATA
SELECT pr.prid, pr.prtgl, pr.prnotransaksi, pr.prstatus, st.nama as prstatusnama, (CASE WHEN po.postatus IN(2,3,4,7) THEN po.poid ELSE 0 END) as poid, (CASE WHEN po.postatus IN(2,3,4,7) THEN GROUP_CONCAT(po.ponotransaksi) ELSE '' END) as ponotransaksi, (CASE WHEN po.postatus IN(2,3,4,7) THEN po.potgl ELSE '1900-01-01' END) as potgl, prd.idprdetail, prd.idbarang, i.bkode, prd.namabarang, prd.jml, SUM((CASE WHEN po.postatus IN(2,3,4,7) THEN pod.jml ELSE 0 END)) as jmlorder, (CASE WHEN po.postatus IN(2,3,4,7) THEN po.posupplier ELSE 0 END) as posupplier, (CASE WHEN po.postatus IN(2,3,4,7) THEN c.kkode ELSE '' END) as kkode, (CASE WHEN po.postatus IN(2,3,4,7) THEN c.knama ELSE '' END) as knama FROM m4_pr pr JOIN m4_pr_detail prd ON pr.prid = prd.idpr JOIN m1_item i ON prd.idbarang = i.bid JOIN m0_status st ON pr.prstatus = st.kode LEFT JOIN m4_po_detail pod ON prd.idprdetail = pod.idprdetail LEFT JOIN m4_po po ON pod.idpo = po.poid AND po.postatus IN(2,3,4,7) LEFT JOIN m1_contact c ON po.posupplier = c.kid GROUP BY pr.prid, prd.idprdetail ORDER BY pr.prtgl, pr.prnotransaksi, prd.urutan;

-- RID=50001637 | MENU=3 | ITEM=16 | RQUERY=1 | NAME=Transaksi PR | FILE=PR
SELECT prid, prcabang, prlokasi, prgudang, prasalbarang, prasalbarangkategori, prjenispembelian, prjenispembeliankategori, prcarabayar, prsumber, prautonotransaksi, prnotransaksi , prtgl, prkodepa, prdimintaoleh, prdimintaolehkontak, prmintake, prtgldipakai, prtermin, prtgljatuhtempo, pruraian,prcatatan, prnoref, prtglnoref, prtglpenutupan, prmatauang, prkurs, prhargatermasukpajak, prtotal, prdiskonpersen, prjmldiskon, prtotalpajak1detail, prtotalpajak2detail, prbiayalainpersen, prbiayalain, prtotaltransaksi, pridsq, prstatussq, prstatuscs, prstatusrq, prstatuspo, prstatusipc, prstatusgrn, prstatusri, prstatusprt, prstatusrealisasi, prstatus, prstatussebelumnya, prjmlrevisi, prcetakanke, prinputuser, prinputtgl, prmodifikasiuser, prmodifikasiuser, prmodifikasitgl, prposting, prpostingtgl, prisclose, prtglawal, prtglakhir, idprdetail, idpr, idbarang, namabarang, tipebarang, jml, satuan, nilaisatuan, jmlbarang, satuanbarang, matauang, kurs, harga, diskon, jmldiskon, pajak1, jmlpajak1, pajak2, jmlpajak2, hargajual, stokterakhir, supplier, cabang, lokasi, gudang, costcenter, divisi, subdivisi, proyek, catatan, urutan, idsqdetail,jmlsq, statussq, jmlcs, statuscs, jmlrq, statusrq, jmlpo, statuspo, jmlipc, statusipc, jmlgrn, statusgrn, jmlri, statusri, jmldnr, statusdnr, jmlprt, statusprt, jmlrealisasi, statusrealisasi, isclose FROM m4_pr pr JOIN m4_pr_detail prd ON pr.prid = prd.idpr ORDER BY pr.prtgl ASC, pr.prid ASC, prd.idprdetail;

-- RID=50003804 | MENU=3 | ITEM=17 | RQUERY=1 | NAME=PURCHASE REQUEST TRACKING | FILE=PRTracking
SELECT pr.prnotransaksi , pr.prtgl, ks.knama AS prmintake , kc.knama AS prdimintaoleh , pr.prcatatan , st.nama AS prstatus , pr.pruraian, b.bkode , prd.namabarang , prd.catatan , prd.jml , prd.satuan , prd.jmlrealisasi , (prd.jml - prd.jmlrealisasi) AS sisa, po.ponotransaksi, pod.idpodetail, po.potgljatuhtempo, pod.jmlrealisasi as realisasipo, ri1.rinotransaksi, ri1.ritgl, kpo.knama as supplier FROM m4_pr pr JOIN m4_pr_detail prd ON pr.prid = prd.idpr JOIN m1_item b ON prd.idbarang = b.bid JOIN m1_contact kc ON pr.prdimintaoleh = kc.kid JOIN m0_status st ON pr.prstatus = st.kode LEFT JOIN m1_contact ks ON pr.prmintake = ks.kid left join m4_po_detail pod on prd.idprdetail = pod.idprdetail left join m4_po po on po.poid = pod.idpo and po.postatus in(2,3,4,7) left join m1_contact kpo on po.posupplier = kpo.kid LEFT JOIN (SELECT IFNULL(grnd.idpodetail,rid.idpodetail) AS idpodetail, rid.idpodetail AS idpori, grnd.idpodetail AS idpogrn, ri.rinotransaksi, ri.ritgl, kkode as risupplier, knama AS namasupplier from m4_ri_detail rid JOIN m4_ri ri ON ri.riid = rid.idri join m1_contact k on ri.risupplier = k.kid left join m4_grn_detail grnd ON grnd.idgrndetail = rid.idgrndetail) as ri1 ON ri1.idpodetail = pod.idpodetail WHERE pr.prstatus in (2,3,4) ORDER BY pr.prnotransaksi, prd.urutan;

