SELECT po.ponotransaksi, po.potgl, ksup.knama AS posupplier, st.nama AS postatus , po.pomatauang , po.pokurs , po.podiskonpersen, po.pojmldiskon, po.pobiayalain, po.pototalpajak1detail, po.pouraian, b.bkode, pod.namabarang , pod.jml , pod.satuan, pod.diskon, pod.harga, ((pod.jml * pod.harga) - pod.jmldiskon) AS total , ksup.kkategorisupplier, ksup.kkategorisuppliernama, sc.sckode , po.pototaltransaksi, pod.catatan, p.pnama, pr.prnotransaksi FROM m4_po po JOIN m4_po_detail pod ON po.poid = pod.idpo JOIN m1_item b ON pod.idbarang = b.bid JOIN m1_contact ksup ON po.posupplier = ksup.kid JOIN m0_status st ON po.postatus = st.kode LEFT JOIN m1_supplier_category sc ON ksup.kkategorisupplier = sc.sckode LEFT JOIN m1_project p ON pod.proyek = p.pkode LEFT JOIN m4_pr_detail prd ON pod.idprdetail = prd.idprdetail LEFT JOIN m4_pr pr ON prd.idpr = pr.prid ORDER BY po.potgl, po.ponotransaksi, pod.urutan;

-- RID=67 | MENU=7 | ITEM=2 | RQUERY=1 | NAME=Daftar Order Pembelian (PO) Outstanding | FILE=POOutstanding
SELECT po.poid , po.ponotransaksi , po.potgl, ks.knama AS posupplier , po.pocatatan , st.nama AS postatus, b.bkode , pod.namabarang , pod.catatan , pod.jml , pod.satuan , (pod.jmlrealisasi / pod.nilaisatuan) AS jmlrealisasi, (pod.jml - (pod.jmlrealisasi / pod.nilaisatuan)) AS sisa FROM m4_po po JOIN m4_po_detail pod ON po.poid = pod.idpo JOIN m1_contact ks ON po.posupplier = ks.kid JOIN m1_item b ON pod.idbarang = b.bid JOIN m0_status st ON po.postatus = st.kode LEFT JOIN m1_supplier_category sc ON ks.kkategorisupplier = sc.sckode WHERE (pod.jml - (pod.jmlrealisasi / pod.nilaisatuan)) > 0 ORDER BY po.potgl, po.poid , po.ponotransaksi , pod.urutan;

-- RID=505 | MENU=7 | ITEM=3 | RQUERY=1 | NAME=Order Pembelian (PO) | FILE=PurchaseOrderDetail1
SELECT l.lnama, f_nominal(po.pototaltransaksi, po.pomatauang) AS terbilang , pohargatermasukpajak, CASE pohargatermasukpajak WHEN 0 THEN "Belum Termasuk Pajak" WHEN 1 THEN "Sudah Termasuk Pajak" END AS "caption" , ksup.kkode , ksup.knama AS posupplier, ksup.k1alamat1 , po.pomatauang, po.pokurs, po.potgl, po.potgljatuhtempo, po.ponotransaksi, st.nama AS postatus, po.pouraian , b.bkode, pod.namabarang , pod.jml, pod.satuan, pod.diskon, pod.harga, ((pod.jml * pod.harga) - pod.jmldiskon) as total , po.pojmldiskon, po.pototalpajak1detail, po.pobiayalain , po.pototaltransaksi , pod.catatan , po.potermin , user1.unama as poinputuser , po.poinputtgl , CASE po.pomodifikasiuser WHEN 0 THEN user1.unama ELSE user2.unama END AS pomodifikasiuser , CASE po.pomodifikasiuser WHEN 0 THEN po.poinputtgl ELSE po.pomodifikasitgl END AS pomodifikasitgl , po.postatus AS statusc FROM m4_po po JOIN m4_po_detail pod ON po.poid = pod.idpo JOIN m1_item b ON pod.idbarang = b.bid JOIN m1_contact ksup ON po.posupplier = ksup.kid JOIN m0_status st ON po.postatus = st.kode JOIN m1_location l ON po.polokasi = l.lkode LEFT JOIN m0_user user1 on po.poinputuser = user1.userid LEFT JOIN m0_user user2 on po.pomodifikasiuser = user2.userid ORDER BY po.potgl, po.ponotransaksi, pod.urutan;

-- RID=72 | MENU=7 | ITEM=4 | RQUERY=1 | NAME=Order Pembelian (PO) | FILE=PurchaseOrderDetail2
SELECT l.lnama, f_nominal(po.pototaltransaksi, po.pomatauang) AS terbilang , pohargatermasukpajak, CASE pohargatermasukpajak WHEN 0 THEN "Belum Termasuk Pajak" WHEN 1 THEN "Sudah Termasuk Pajak" END AS "caption" , ksup.kkode , ksup.knama AS posupplier, ksup.k1alamat1 , po.pomatauang, po.pokurs, po.potgl, po.potgljatuhtempo, po.ponotransaksi, st.nama AS postatus, po.pouraian , b.bkode, pod.namabarang , pod.jml, pod.satuan, pod.diskon, pod.harga, ((pod.jml * pod.harga) - pod.jmldiskon) as total , po.pojmldiskon, po.pototalpajak1detail, po.pobiayalain , po.pototaltransaksi , pod.catatan FROM m4_po po JOIN m4_po_detail pod ON po.poid = pod.idpo JOIN m1_item b ON pod.idbarang = b.bid JOIN m1_contact ksup ON po.posupplier = ksup.kid JOIN m0_status st ON po.postatus = st.kode JOIN m1_location l ON po.polokasi = l.lkode ORDER BY po.potgl, po.ponotransaksi, pod.urutan;

-- RID=520 | MENU=7 | ITEM=5 | RQUERY=1 | NAME=Order Pembelian (PO)  | FILE=PurchaseOrderDetail2_UD
SELECT ksup.knama AS posupplier, po.pomatauang, po.pokurs, po.potgl, po.ponotransaksi, st.nama AS postatus, po.pouraian , b.bkode, pod.namabarang , pod.jml, pod.satuan, pod.diskon, pod.harga, ((pod.jml * pod.harga) - pod.jmldiskon) as total , po.pojmldiskon, po.pototalpajak1detail, po.pobiayalain FROM m4_po po JOIN m4_po_detail pod ON po.poid = pod.idpo JOIN m1_item b ON pod.idbarang = b.bid JOIN m1_contact ksup ON po.posupplier = ksup.kid JOIN m0_status st ON po.postatus = st.kode ORDER BY po.potgl, po.ponotransaksi, pod.urutan;

-- RID=569 | MENU=7 | ITEM=6 | RQUERY=1 | NAME=Order Pembelian (PO) | FILE=PurchaseOrderDetail1_UD2
SELECT (SELECT f_nominal(ROUND(po2.pototaltransaksi,2), po2.pomatauang) FROM m4_po po2 JOIN m4_po_detail pod2 ON po2.poid = pod2.idpo WHERE po2.poid = po.poid GROUP BY po2.poid ) AS terbilang , po.pototalpajak2detail , ksup.knama AS posupplier, po.pomatauang, po.pokurs, po.potgl, po.ponotransaksi, st.nama AS postatus, po.pouraian , b.bkode, pod.namabarang , pod.jml, pod.satuan, pod.diskon, pod.harga, ((pod.jml * pod.harga) - pod.jmldiskon) as total , po.pojmldiskon, po.pototalpajak1detail, po.pobiayalain , userr.unama , po.pocatatan FROM m4_po po JOIN m4_po_detail pod ON po.poid = pod.idpo JOIN m1_item b ON pod.idbarang = b.bid JOIN m1_contact ksup ON po.posupplier = ksup.kid JOIN m0_status st ON po.postatus = st.kode LEFT JOIN m0_user userr ON po.poinputuser = userr.userid ORDER BY po.potgl, po.ponotransaksi, pod.urutan;

-- RID=294 | MENU=7 | ITEM=7 | RQUERY=1 | NAME=Daftar PO Terkait GRN dan RI | FILE=POGRNRI
SELECT pod.idpodetail , po.ponotransaksi, po.potgl, ks.knama AS posupplier , b.bkode , pod.tipebarang, pod.namabarang, pod.jml , pod.satuan, grnd.idgrndetail , grn.grnnotransaksi, grn.grntgl , grnd.jml AS grnjml , grnd.satuan AS grnsatuan, ri.rinotransaksi, ri.ritgl , rid.jml AS rijml , rid.satuan AS risatuan FROM m4_po po JOIN m4_po_detail pod ON po.poid = pod.idpo JOIN m1_contact ks ON po.posupplier = ks.kid JOIN m1_item b ON pod.idbarang = b.bid LEFT JOIN m4_grn_detail grnd ON pod.idpodetail = grnd.idpodetail JOIN m4_grn grn ON grnd.idgrn = grn.grnid LEFT JOIN m4_ri_detail rid ON grnd.idgrndetail = rid.idgrndetail JOIN m4_ri ri ON rid.idri = ri.riid ORDER BY po.ponotransaksi , pod.idpodetail , grn.grnnotransaksi , grnd.idgrndetail , ri.rinotransaksi;

-- RID=297 | MENU=7 | ITEM=8 | RQUERY=1 | NAME=Order Pembelian (PO) | FILE=PurchaseOrderDetailValas
SELECT pod.urutan, po.ponotransaksi, po.potgl, po.pocatatan, pod.namabarang, pod.tipebarang, pod.harga, (pod.harga * pod.kurs) as hargarupiah , ((pod.harga * pod.kurs) * pod.jml ) AS totalrupiah , (pod.harga * pod.jml ) AS total , pod.jml, pod.diskon, pod.satuan, po.pototalpajak1detail, (po.pototalpajak1detail * po.pokurs) AS pototalpajak1detailrupiah, po.pototaltransaksi , (po.pototaltransaksi * po.pokurs) AS pototaltransaksirupiah , b.bkode AS kodebarang, ksup.knama AS supplier, ksup.k1notelp1, po.posupplierkontak, po.pomatauang, pod.jmldiskon FROM m4_po po JOIN m4_po_detail pod ON po.poid = pod.idpo JOIN m1_item b ON pod.idbarang = b.bid JOIN m1_contact ksup ON po.posupplier = ksup.kid ORDER BY po.ponotransaksi, pod.urutan;

-- RID=68 | MENU=7 | ITEM=9 | RQUERY=1 | NAME=Daftar Order Pembelian (PO) Outstanding Sisa | FILE=POOutstandingSisa
SELECT po.poid , po.ponotransaksi , po.potgl, ks.knama AS posupplier , kb.knama AS pobagianpembelian , po.pocatatan , CASE po.postatus WHEN 0 THEN "Draft" WHEN 1 THEN "Minta Approve" WHEN 2 THEN "Approved" WHEN 3 THEN "Inprogress" WHEN 4 THEN "Complete" WHEN 5 THEN "Revisi" WHEN 6 THEN "Reject" WHEN 7 THEN "Close" WHEN 8 THEN "Approve 1" WHEN 9 THEN "Approve 2" WHEN 10 THEN "Approve 3" WHEN 11 THEN "Approve 4" WHEN 12 THEN "Hapus" END AS postatus, b.bkode , pod.tipebarang , pod.namabarang , pod.catatan , pod.jml , pod.satuan , pod.jmlgrn , pod.jmlri , pod.jmldnr , pod.jmlprt FROM m4_po po JOIN m4_po_detail pod ON po.poid = pod.idpo JOIN m1_contact ks ON po.posupplier = ks.kid JOIN m1_contact kb ON po.pobagianpembelian = kb.kid JOIN m1_item b ON pod.idbarang = b.bid ORDER BY po.poid , po.ponotransaksi , pod.urutan;

-- RID=69 | MENU=7 | ITEM=10 | RQUERY=1 | NAME=Daftar Order Pembelian (PO) Per Produk | FILE=ListPurchaseOrder_product
SELECT b.bid , b.bkode , pod.namabarang , po.ponotransaksi , po.potgl , ksup.knama AS posupplier , SUM(pod.jml) AS jml , pod.satuan, SUM(pod.diskon) AS diskon, pod.harga, sum((pod.jml * pod.harga) - pod.jmldiskon) AS total FROM m4_po po JOIN m4_po_detail pod ON po.poid = pod.idpo JOIN m1_item b ON pod.idbarang = b.bid JOIN m1_contact ksup ON po.posupplier = ksup.kid JOIN m0_status st ON po.postatus = st.kode LEFT JOIN m1_supplier_category sc ON ksup.kkategorisupplier = sc.sckode GROUP BY pod.idbarang, b.bid, b.bkode, pod.namabarang, pod.satuan, pod.harga, pod.idpo ORDER BY pod.idbarang , b.bid, pod.namabarang;

-- RID=70 | MENU=7 | ITEM=11 | RQUERY=1 | NAME=Order Pembelian (PO) | FILE=PurchaseOrderDetail
SELECT pod.urutan, po.ponotransaksi, po.potgl, po.pomatauang, pod.namabarang, pod.tipebarang, pod.harga, (((pod.harga ) * pod.jml ) - pod.jmldiskon) AS total , pod.diskon, pod.jml, po.pototalpajak1detail, po.pojmldiskon, b.bkode, pod.satuan, po.posupplierkontak AS YTH, ksup.knama, po.po1alamat1 AS poalamat1, po.pocatatan FROM m4_po po JOIN m1_contact ksup ON po.posupplier = ksup.kid JOIN m4_po_detail pod ON po.poid = pod.idpo JOIN m1_item b ON pod.idbarang = b.bid ORDER BY po.potgl , po.ponotransaksi, pod.urutan;

-- RID=74 | MENU=7 | ITEM=12 | RQUERY=1 | NAME=Order Pembelian (PO) | FILE=PurchaseOrderDetail4
SELECT pod.urutan, IFNULL(LEFT(blg.blgnamalokasi, 3),'-') AS lokasi, po.ponotransaksi, po.potgl, po.pocatatan, pod.namabarang, pod.tipebarang, pod.jml, pod.satuan, b.bkode AS kodebarang, blg.blgnamalokasi FROM m4_po po JOIN m4_po_detail pod ON po.poid = pod.idpo JOIN m1_item b ON pod.idbarang = b.bid JOIN m1_contact ksup ON po.posupplier = ksup.kid LEFT JOIN m1_item_location_warehouse blg ON (po.pogudang = blg.blggudang AND b.bid = blg.blgidbarang) ORDER BY po.ponotransaksi, IFNULL(LEFT(blg.blgnamalokasi, 3), '-'), pod.urutan;

-- RID=76 | MENU=7 | ITEM=13 | RQUERY=1 | NAME=Daftar Order Pembelian (PO) Tanpa Harga | FILE=ListPurchaseOrderWithoutPrice
SELECT pod.urutan, b.bnama, po.ponotransaksi, po.potgl, pod.jmldiskon, pod.jml, pod.diskon, po.pototalpajak1detail as pototalpajak , b.bkode AS kodebarang, pod.catatan, pod.satuan, pod.namabarang , ksup.knama AS namasupplier, kp.knama AS customer, pod.matauang, blg.blgnamalokasi, pod.tipebarang, DATEDIFF(DATE(NOW()) , potgl) AS umur FROM m4_po po JOIN m4_po_detail pod ON (po.poid = pod.idpo) JOIN m1_item b ON (pod.idbarang = b.bid) JOIN m1_contact ksup ON (po.posupplier = ksup.kid) JOIN m1_contact kp ON (po.pobagianpembelian = kp.kid) LEFT JOIN m1_item_location_warehouse blg ON (b.bid = blg.blgidbarang) AND (po.pogudang = blg.blggudang) ORDER BY po.ponotransaksi, pod.urutan;

-- RID=77 | MENU=7 | ITEM=14 | RQUERY=1 | NAME=Order Pembelian (PO) | FILE=PurchaseOrderDetailWithoutPrice1
SELECT po.ponotransaksi, po.potgl, ks.knama AS posupplier, po.posupplierkontak AS YTH , po.pocatatan, b.bkode , pod.tipebarang, pod.namabarang , pod.jml , pod.satuan, pod.catatan FROM m4_po po JOIN m4_po_detail pod ON po.poid = pod.idpo JOIN m1_contact ks ON po.posupplier = ks.kid JOIN m1_item b ON pod.idbarang = b.bid GROUP BY po.ponotransaksi, b.bkode, pod.tipebarang, pod.namabarang, pod.satuan ORDER BY po.ponotransaksi, pod.urutan;

