-- RID=50003805 | MENU=7 | ITEM=27 | RQUERY=1 | NAME=PURCHASE ORDER TRACKING | FILE=POTracking
SELECT po.ponotransaksi , po.potgl, po.pocatatan , po.pouraian, st.nama AS postatus , b.bkode , pod.namabarang , pod.catatan , pod.jml , pod.satuan , pod.harga, (pod.jml * pod.harga) - pod.jmldiskon as subtotal, pod.urutan , ri1.ritotaltransaksi , ri1.urutan as urutanri , pod.jmlrealisasi AS realisasi, pod.idpodetail, po.potgljatuhtempo, ri1.rinotransaksi, ri1.ritgl, kpo.knama as supplier, ri1.ritotaltransaksi as totalinvoice, ri1.rijmlbayar as paid, ri1.ritotaltransaksi - ri1.rijmlbayar as outstanding, pr.prnotransaksi, pr.prtgl, cr.csimbol, ri1.riid FROM m4_po po JOIN m4_po_detail pod ON po.poid = pod.idpo JOIN m1_item b ON pod.idbarang = b.bid JOIN m0_status st ON po.postatus = st.kode join m1_contact kpo on po.posupplier = kpo.kid join m1_currency cr on po.pomatauang = cr.ckode left join m4_pr_detail prd on prd.idprdetail = pod.idprdetail left join m4_pr pr on pr.prid = prd.idpr LEFT JOIN (SELECT ri.riid, IFNULL(grnd.idpodetail,rid.idpodetail) AS idpodetail, rid.idpodetail AS idpori, grnd.idpodetail AS idpogrn, ri.rinotransaksi, ri.ritgl, kkode as risupplier, knama AS namasupplier, ri.ritotaltransaksi, ri.rijmlbayar, rid.urutan, ri.ristatus from m4_ri_detail rid JOIN m4_ri ri ON ri.riid = rid.idri join m1_contact k on ri.risupplier = k.kid left join m4_grn_detail grnd ON grnd.idgrndetail = rid.idgrndetail) as ri1 ON ri1.idpodetail = pod.idpodetail AND ri1.ristatus IN (2,3,4,7) WHERE po.postatus in (2,3,4) ORDER BY po.ponotransaksi, pod.urutan;

