-- RID=79 | MENU=8 | ITEM=1 | RQUERY=1 | NAME=Daftar UM Pembelian (AP) | FILE=ListAdvancePurchaseGlobal
SELECT CASE ap.apjenis WHEN 0 then "UM Pembelian" WHEN 1 then "Titipan" END AS apjenis , ks.knama , ap.apnorek, po.ponotransaksi, ap.apnotransaksi , ap.aptgl, st.nama AS apstatus , CASE app.carabayar WHEN 0 then "Cash" WHEN 1 then "Transfer" WHEN 2 then "Check/Giro" WHEN 3 then "Other" end as carabayar, CASE app.carabayar WHEN 2 THEN app.rekgiro ELSE app.rekbank END AS noakun , CASE app.carabayar WHEN 2 then coa2.cnama ELSE coa.cnama END AS namaakun, app.matauang, app.jumlah, app.jumlahvalas FROM m4_ap ap JOIN m4_ap_pay app ON ap.apid = app.idap JOIN m1_contact ks ON ap.apkontak = ks.kid JOIN m0_status st ON ap.apstatus = st.kode LEFT JOIN m4_po po ON ap.apidpo = po.poid LEFT JOIN m1_coa coa ON app.rekbank = coa.cnomor LEFT JOIN m1_coa coa2 ON app.rekgiro = coa2.cnomor ORDER BY ap.aptgl, ap.apnotransaksi , app.urutan;

