-- RID=146 | MENU=10 | ITEM=8 | RQUERY=1 | NAME=Daftar Penerimaan Barang (GRN) Outstanding Sisa | FILE=GRNOutstandingSisa
SELECT grn.grnnotransaksi , grn.grnid , grn.grntgl , ks.knama AS grnsupplier , kb.knama AS grnbagianpembelian , grn.grncatatan , CASE grn.grnstatus WHEN 0 THEN "Draft" WHEN 1 THEN "Minta Approve" WHEN 2 THEN "Approved" WHEN 3 THEN "Inprogress" WHEN 4 THEN "Complete" WHEN 5 THEN "Revisi" WHEN 6 THEN "Reject" WHEN 7 THEN "Close" WHEN 8 THEN "Approve 1" WHEN 9 THEN "Approve 2" WHEN 10 THEN "Approve 3" WHEN 11 THEN "Approve 4" WHEN 12 THEN "Hapus" END AS grnstatus , b.bkode , grnd.tipebarang , grnd.namabarang , grnd.catatan , grnd.jml , grnd.satuan , grnd.jmlri , grnd.jmldnr , grnd.jmlprt FROM m4_grn grn JOIN m4_grn_detail grnd ON grn.grnid = grnd.idgrn JOIN m1_contact ks ON grn.grnsupplier = ks.kid JOIN m1_contact kb ON grn.grnbagianpembelian = kb.kid JOIN m1_item b ON grnd.idbarang = b.bid ORDER BY grn.grnid , grn.grnnotransaksi , grnd.urutan;

-- RID=147 | MENU=10 | ITEM=9 | RQUERY=1 | NAME=Daftar Penerimaan Barang (GRN) Per Produk | FILE=ListGoodReceiptNote_product
SELECT b.bid , b.bkode , grd.namabarang , gr.grnnotransaksi , gr.grntgl , ksup.knama AS grnsupplier , w.wnama AS gudang , SUM(grd.jml) AS jml , grd.satuan , po.ponotransaksi , gr.grncatatan FROM m4_grn gr JOIN m4_grn_detail grd ON gr.grnid = grd.idgrn JOIN m1_item b ON grd.idbarang = b.bid JOIN m1_contact ksup ON gr.grnsupplier = ksup.kid JOIN m0_status st ON gr.grnstatus = st.kode JOIN m1_warehouse w ON gr.grngudang = w.wkode LEFT JOIN m4_po_detail pod ON grd.idpodetail = pod.idpodetail LEFT JOIN m4_po po on pod.idpo = po.poid left JOIN m1_supplier_category sc ON ksup.kkategorisupplier = sc.sckode GROUP BY grd.idbarang, b.bid, b.bkode, grd.namabarang, grd.satuan, grd.idgrn ORDER BY grd.idbarang , b.bid, grd.namabarang;

-- RID=286 | MENU=10 | ITEM=10 | RQUERY=1 | NAME=Daftar GRN Terkait RI dan DNR | FILE=GRNRIDNR
SELECT grnd.idgrndetail , grn.grnnotransaksi , grn.grntgl, ks.knama AS grnsupplier, grnd.jml , grnd.satuan, b.bkode, grnd.tipebarang , grnd.namabarang , rid.idridetail , ri.rinotransaksi , ri.ritgl, rid.jml as rijml , rid.satuan AS risatuan , dnr.dnrnotransaksi , dnr.dnrtgl, dnrd.jml AS dnrjml , dnrd.satuan AS dnrsatuan FROM m4_grn grn JOIN m4_grn_detail grnd ON grn.grnid = grnd.idgrn JOIN m1_contact ks ON grn.grnsupplier = ks.kid JOIN m1_item b ON grnd.idbarang = b.bid LEFT JOIN m4_ri_detail rid ON grnd.idgrndetail = rid.idgrndetail JOIN m4_ri ri ON rid.idri = ri.riid LEFT JOIN m4_dnr_detail dnrd ON rid.idridetail = dnrd.idridetail JOIN m4_dnr dnr ON dnrd.iddnr = dnr.dnrid ORDER BY grnd.idgrndetail , grn.grnnotransaksi , rid.idridetail , ri.rinotransaksi , dnr.dnrnotransaksi;

-- RID=150 | MENU=10 | ITEM=11 | RQUERY=1 | NAME=Penerimaan Barang (GRN) | FILE=GoodReceiptNoteDetailPerLocation1
SELECT grd.urutan, IFNULL(LEFT(blg.blgnamalokasi, 3), '-') AS lokasi, IFNULL((blg.blgnamalokasi),'-') AS blgnamalokasi, gr.grntgl, gr.grnnotransaksi, gr.grncatatan, grd.catatan, grd.tipebarang, grd.namabarang, SUM(grd.jml) AS jml, b.bkode, grd.satuan, ksup.knama AS supplier, g.wnama, gr.grnsupplierkontak, gr. grn1alamat1 FROM m4_grn gr JOIN m4_grn_detail grd ON gr.grnid = grd.idgrn JOIN m1_item b ON grd.idbarang = b.bid JOIN m1_contact ksup ON gr.grnsupplier = ksup.kid LEFT JOIN m1_item_location_warehouse blg ON grd.idbarang = blg.blgidbarang AND gr.grngudang = blg.blggudang LEFT JOIN m1_warehouse g ON gr.grngudang = g.wkode GROUP BY gr.grnnotransaksi, IFNULL(LEFT(blg.blgnamalokasi, 3), '-'), b.bkode, grd.tipebarang, grd.namabarang, grd.satuan ORDER BY gr.grnnotransaksi, IFNULL(LEFT(blg.blgnamalokasi, 3), '-'), IFNULL((blg.blgnamalokasi),'-'), grd.urutan;

-- RID=1563 | MENU=10 | ITEM=12 | RQUERY=1 | NAME=Bukti Barang Keluar Retur | FILE=BuktiBarangKeluarRetur
