-- RID=152 | MENU=11 | ITEM=1 | RQUERY=1 | NAME=Daftar Invoice Pembelian (RI)  | FILE=ListReceiveInvoice_kwsg
SELECT ri.rinotransaksi , ri.ritgl , ks.kkode AS kodesupplier, ks.knama AS risupplier , st.nama AS ristatus , ri.rimatauang , ri.rikurs , ri.ridiskonpersen , ri.rijmldiskon , ri.ribiayalain , ri.ribiayalainpersen , ri.ritotalpajak1detail , (ri.ribiayalain + ri.ritotalpajak1detail - ri.rijmldiskon) AS a , b.bkode , rid.namabarang , b.bkategori, b.btipe, b.bdivisi, rid.satuan , rid.jml , grnd.jml as jmlGRN, IFNULL(pod2.jml,pod.jml) as jmlPO, rid.harga , (rid.jml * rid.harga) AS bruto , rid.diskon, rid.jmldiskon , ((rid.jml * rid.harga) - rid.jmldiskon) AS total, rid.pajak1, rid.jmlpajak1, rid.pajak2, rid.jmlpajak2, grn.grnnotransaksi, grn.grngudang as gudangGRN, ri.rigudang as gudangRI, IFNULL(po2.ponotransaksi,po1.ponotransaksi) as nopo, b.brekpersediaan, b.brekpenjualan, b.brekhargapokok, b.brekkonsinyasi, ks.krekhutang, rid.costcenter, rid.divisi, rid.subdivisi, rid.proyek, ri.ritgljatuhtempo ,ri.ritermin FROM m4_ri ri JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_item b ON rid.idbarang = b.bid JOIN m1_contact ks ON ri.risupplier = ks.kid LEFT join m1_item_category ic ON b.bkategori = ic.ickode left JOIN m4_po_detail pod1 ON rid.idpodetail = pod1.idpodetail LEFT JOIN m4_po po1 ON pod1.idpo = po1.poid LEFT JOIN m4_grn_detail grnd ON rid.idgrndetail = grnd.idgrndetail LEFT JOIN m4_grn grn ON grnd.idgrn = grn.grnid left JOIN m4_po_detail pod ON rid.idpodetail = pod.idpodetail LEFT JOIN m4_po po ON pod.idpo = po.poid LEFT JOIN m0_status st ON st.kode = ri.ristatus left JOIN m4_po_detail pod2 ON grnd.idpodetail = pod2.idpodetail LEFT JOIN m4_po po2 ON pod2.idpo = po2.poid ORDER BY ri.riid , rid.urutan;

-- RID=460 | MENU=11 | ITEM=2 | RQUERY=1 | NAME=Daftar Invoice Pembelian (RI) 1 | FILE=ListReceiveInvoice1_kwsg
SELECT ri.rihargatermasukpajak , CASE ri.rihargatermasukpajak WHEN 0 THEN "Belum Termasuk Pajak" WHEN 1 THEN "Sudah Termasuk Pajak" END AS "caption" , ri.rinotransaksi , ri.ritgl , k.knama AS risupplier , st.nama AS ristatus , ri.rimatauang , ri.rikurs , ri.ridiskonpersen , ri.rijmldiskon , ri.ribiayalain , ri.ribiayalainpersen , ri.ritotalpajak1detail , (ri.ribiayalain + ri.ritotalpajak1detail - ri.rijmldiskon) AS a , b.bkode , rid.namabarang , rid.satuan , rid.jml , rid.harga , (rid.jml * rid.harga) AS bruto , rid.diskon, rid.jmldiskon , ((rid.jml * rid.harga) - rid.jmldiskon) AS total , ri.ritgljatuhtempo FROM m4_ri ri JOIN m1_contact k ON ri.risupplier = k.kid JOIN m0_status st ON ri.ristatus = st.kode JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_item b ON b.bid = rid.idbarang ORDER BY ri.ritgl , ri.rinotransaksi;

-- RID=563 | MENU=11 | ITEM=3 | RQUERY=1 | NAME=Daftar Invoice Pembelian (RI) 3 | FILE=ListReceiveInvoice2
SELECT ri.rinotransaksi , ri.ritgl , k.knama AS risupplier , st.nama AS ristatus , ri.rimatauang , ri.rikurs , ri.ridiskonpersen , ri.rijmldiskon , ri.ribiayalain , ri.ribiayalainpersen , ri.ritotalpajak1detail , (ri.ribiayalain + ri.ritotalpajak1detail - ri.rijmldiskon) AS a , b.bkode , rid.namabarang , rid.satuan , rid.jml , rid.harga , (rid.jml * rid.harga) AS bruto , rid.diskon, rid.jmldiskon , ((rid.jml * rid.harga) - rid.jmldiskon) AS total FROM m4_ri ri JOIN m1_contact ks ON ri.risupplier = ks.kid JOIN m0_status statuss ON ri.ristatus = statuss.kode LEFT JOIN m1_supplier_category sc ON ks.kkategorisupplier = sc.sckode ORDER BY ri.ritgl , ri.rinotransaksi;

-- RID=287 | MENU=11 | ITEM=4 | RQUERY=1 | NAME=Daftar Invoice Pembelian (RI) Outstanding | FILE=RIOutstanding
SELECT ri.rinotransaksi , ri.riid , ri.ritgl , ks.knama AS risupplier , ri.riuraian, st.nama AS ristatus , b.bkode , rid.namabarang , rid.catatan , rid.jml , rid.satuan , (rid.jmlrealisasi / rid.nilaisatuan) AS jmlrealisasi , (rid.jml - ((rid.jmlrealisasi / rid.nilaisatuan))) AS sisa , ks.kkategorisupplier, ri.ritgljatuhtempo FROM m4_ri ri JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_contact ks ON ri.risupplier = ks.kid JOIN m1_item b ON rid.idbarang = b.bid JOIN m0_status st ON ri.ristatus = st.kode LEFT JOIN m1_supplier_category sc ON ks.kkategorisupplier = sc.sckode ORDER BY ri.ritgl , ri.rinotransaksi, rid.urutan;

-- RID=153 | MENU=11 | ITEM=5 | RQUERY=1 | NAME=Invoice Pembelian (RI) | FILE=ReceiveInvoiceDetail1_new
SELECT w.wnama, f_nominal(ritotaltransaksi, rimatauang) AS terbilang , rihargatermasukpajak , CASE rihargatermasukpajak WHEN 0 THEN "Belum Termasuk Pajak" WHEN 1 THEN "Sudah Termasuk Pajak" END AS "caption" , ks.kkode , ks.knama AS risupplier , ks.k1alamat1 , ri.rimatauang , ri.rikurs , ri.riuraian , ri.ritgl, ri.rinotransaksi , st.nama AS ristatus , (SELECT GROUP_CONCAT(DISTINCT po2.ponotransaksi) from m4_po_detail pod2 join m4_po po2 ON pod2.idpo = po2.poid join m4_ri_detail rid on pod2.idpodetail = rid.idpodetail join m4_ri ri2 on rid.idri = ri2.riid WHERE ri2.riid = ri.riid GROUP BY ri2.riid ) as ponotransaksi , b.bkode , rii.namabarang , grn.grnnotransaksi, rii.jml , rii.satuan , rii.diskon , rii.jmldiskon , rii.harga , rii.jmlpajak1, ((rii.jml * rii.harga) - rii.jmldiskon) as total , ri.ridiskonpersen , ri.rijmldiskon, ri.ritotalpajak1detail, ri.ritotalpajak2detail, ri.ribiayalain, ri.ritotaltransaksi, ri.ritgljatuhtempo , user1.unama as poinputuser , ri.riinputtgl , case when ristatus in(2,3,4) and rimodifikasiuser = 0 then user1.unama when rimodifikasiuser = 0 then '' else user2.unama end AS pomodifikasiuser , case when ristatus in(2,3,4) and rimodifikasiuser = 0 then ri.riinputtgl when rimodifikasiuser = 0 then '' else rimodifikasitgl end AS rimodifikasitgl , ri.ristatus as statusc, ks.kbank, ks.knorekening FROM m4_ri ri JOIN m4_ri_detail rii ON ri.riid = rii.idri JOIN m1_contact ks ON ri.risupplier = ks.kid JOIN m1_item b ON rii.idbarang = b.bid JOIN m0_status st ON ri.ristatus = st.kode JOIN m1_warehouse w ON ri.rigudang = w.wkode LEFT JOIN m4_po_detail pod ON rii.idpodetail = pod.idpodetail LEFT JOIN m4_po po ON pod.idpo = po.poid LEFT JOIN m4_grn_detail grnd ON rii.idgrndetail = grnd.idgrndetail LEFT JOIN m4_grn grn ON grnd.idgrn = grn.grnid LEFT JOIN m0_user user1 on ri.riinputuser = user1.userid LEFT JOIN m0_user user2 on ri.rimodifikasiuser = user2.userid ORDER BY ri.rinotransaksi, rii.urutan;

