-- RID=288 | MENU=11 | ITEM=9 | RQUERY=1 | NAME=Daftar Invoice Pembelian (RI) Outstanding Sisa | FILE=RIOutstandingSIsa
SELECT ri.rinotransaksi , ri.riid , ri.ritgl , ks.knama AS risupplier , kb.knama AS ribagianpembelian , ri.ricatatan , CASE ri.ristatus WHEN 0 THEN "Draft" WHEN 1 THEN "Minta Approve" WHEN 2 THEN "Approved" WHEN 3 THEN "Inprogress" WHEN 4 THEN "Complete" WHEN 5 THEN "Revisi" WHEN 6 THEN "Reject" WHEN 7 THEN "Close" WHEN 8 THEN "Approve 1" WHEN 9 THEN "Approve 2" WHEN 10 THEN "Approve 3" WHEN 11 THEN "Approve 4" WHEN 12 THEN "Hapus" END AS ristatus , b.bkode , rid.tipebarang , rid.namabarang , rid.catatan , rid.jml , rid.satuan , rid.jmldnr , rid.jmlprt FROM m4_ri ri JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_contact ks ON ri.risupplier = ks.kid JOIN m1_contact kb ON ri.ribagianpembelian = kb.kid JOIN m1_item b ON rid.idbarang = b.bid ORDER BY ri.riid , ri.rinotransaksi, rid.urutan;

-- RID=289 | MENU=11 | ITEM=10 | RQUERY=1 | NAME=Daftar RI Terkait VPP dan VP | FILE=RIVPPVP
SELECT rid.idridetail , ri.rinotransaksi , ri.ritgl , ks.knama AS risupplier , b.bkode , rid.tipebarang , rid.namabarang , rid.jml , rid.satuan, vppd.idvppdetail , vpp.vppnotransaksi, vpp.vpptgl , vppd.jmlvp, vp.vpnotransaksi , vp.vptgl, vpd.jmlbayar FROM m4_ri ri JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_contact ks ON ri.risupplier = ks.kid JOIN m1_item b ON rid.idbarang = b.bid LEFT JOIN m4_vpp_detail vppd ON rid.idri = vppd.idtransaksi JOIN m4_vpp vpp ON vppd.idvpp = vpp.vppid LEFT JOIN m4_vp_detail vpd ON vppd.idvppdetail = vpd.idvppdetail JOIN m4_vp vp ON vpd.idvp = vp.vpid ORDER BY rid.idridetail , ri.rinotransaksi , vpp.vppnotransaksi, vpp.vpptgl , vp.vpnotransaksi;

-- RID=290 | MENU=11 | ITEM=11 | RQUERY=1 | NAME=Daftar RI Terkait DNR dan PRT | FILE=RIDNRPRT
SELECT rid.idridetail , ri.rinotransaksi, ri.ritgl, ks.knama AS risupplier, rid.jml , rid.satuan, b.bkode , rid.tipebarang, rid.namabarang , dnrd.iddnrdetail , dnr.dnrnotransaksi , dnr.dnrtgl, dnrd.jml AS dnrjml , dnrd.satuan AS dnrsatuan , prt.prtnotransaksi, prt.prttgl, prtd.jml AS prtjml, prtd.satuan AS prtsatuan FROM m4_ri ri JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_contact ks ON ri.risupplier = ks.kid JOIN m1_item b ON rid.idbarang = b.bid LEFT JOIN m4_dnr_detail dnrd ON rid.idridetail = dnrd.idridetail JOIN m4_dnr dnr ON dnrd.iddnr = dnr.dnrid LEFT JOIN m4_prt_detail prtd ON dnrd.iddnrdetail = prtd.iddnrdetail JOIN m4_prt prt on prtd.idprt = prt.prtid ORDER BY rid.idridetail , ri.rinotransaksi, dnrd.iddnrdetail , dnr.dnrnotransaksi , prt.prtnotransaksi;

-- RID=299 | MENU=11 | ITEM=12 | RQUERY=1 | NAME=Invoice Pembelian (RI) Valas | FILE=ReceiveInvoiceDetailValas1
SELECT ks.kkode , ks.knama AS risupplier , concat(ri.rinoref," ",ri.ritglbayarpajak) AS rinoref, grn.grnnotransaksi, ri.ritgl, ri.rinotransaksi, ri.rimatauang, ri.rikurs, b.bkode, rii.tipebarang, rii.namabarang, po.ponotransaksi, rii.jml, rii.satuan, rii.harga , (rii.harga * rii.kurs) AS hargarupiah , rii.diskon, rii.jmldiskon, ((rii.jml * rii.harga) - rii.jmldiskon) AS total , ((rii.jml * (rii.harga * rii.kurs)) - rii.jmldiskon) AS totalrupiah , (ri.ritotalpajak1detail + ri.ritotalpajak2detail) AS totalpajak, ((ri.ritotalpajak1detail + ri.ritotalpajak2detail) * ri.rikurs) AS totalpajakrupiah , ri.ritotaltransaksi , (ri.ritotaltransaksi * ri.rikurs) AS ritotaltransaksirupiah FROM m4_ri ri JOIN m4_ri_detail rii ON ri.riid = rii.idri JOIN m1_item b ON rii.idbarang = b.bid JOIN m1_contact ks ON ri.risupplier = ks.kid LEFT join m1_item_category ic ON b.bkategori = ic.ickode left JOIN m4_po_detail pod ON rii.idpodetail = pod.idpodetail LEFT JOIN m4_po po ON pod.idpo = po.poid LEFT JOIN m4_grn_detail grnd ON rii.idgrndetail = grnd.idgrndetail LEFT JOIN m4_grn grn ON grnd.idgrn = grn.grnid GROUP BY ri.rinotransaksi , po.ponotransaksi, b.bkode, rii.tipebarang, rii.namabarang, rii.satuan, rii.harga ORDER BY ri.rinotransaksi, rii.urutan;

