-- RID=424126 | MENU=11 | ITEM=36 | RQUERY=1 | NAME=Invoice Pembelian (RI) | FILE=ListReceiveInvoice2_kwsg
SELECT ri.ritotaltransaksi , ri.riid , ri.rinotransaksi , ri.ritgl , k.knama AS risupplier , st.nama AS ristatus , ri.rimatauang , ri.rikurs , ri.ridiskonpersen , ri.rijmldiskon , ri.ribiayalain , ri.ribiayalainpersen , ri.ritotalpajak1detail , (ri.ribiayalain + ri.ritotalpajak1detail - ri.rijmldiskon) AS a , rid.idbarang , b.bkode , rid.namabarang , rid.satuan , rid.jml , rid.harga , (rid.jml * rid.harga) AS bruto , rid.diskon, rid.jmldiskon , ((rid.jml * rid.harga) - rid.jmldiskon) AS total , rid.jmlpajak1 , rid.jmlpajak2 , CASE ri.rihargatermasukpajak WHEN 0 THEN (rid.harga - (rid.jmldiskon / rid.jml) + (rid.jmlpajak1 / rid.jml) + (rid.jmlpajak2 / rid.jml)) WHEN 1 THEN rid.harga - (rid.jmldiskon / rid.jml) END AS harganet FROM m4_ri ri JOIN m1_contact k ON ri.risupplier = k.kid JOIN m0_status st ON ri.ristatus = st.kode JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_item b ON b.bid = rid.idbarang ORDER BY ri.riid , rid.urutan;

-- RID=424127 | MENU=11 | ITEM=37 | RQUERY=1 | NAME=Invoice Pembelian (RI) | FILE=ListReceiveInvoice3_kwsg
SELECT ri.riid , ri.rinotransaksi , ri.ritgl , k.knama AS risupplier , st.nama AS ristatus , ri.rimatauang , ri.rikurs , ri.ridiskonpersen , ri.rijmldiskon , ri.ribiayalain , ri.ribiayalainpersen , ri.ritotalpajak1detail , (ri.ribiayalain + ri.ritotalpajak1detail - ri.rijmldiskon) AS a , rid.idbarang , b.bkode , rid.namabarang , rid.satuan , rid.jml , rid.harga , (rid.jml * rid.harga) AS bruto , rid.diskon, rid.jmldiskon , ((rid.jml * rid.harga)) AS total FROM m4_ri ri JOIN m1_contact k ON ri.risupplier = k.kid JOIN m0_status st ON ri.ristatus = st.kode JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_item b ON b.bid = rid.idbarang ORDER BY rid.idbarang ASC , ri.ritgl ASC;

-- RID=50000531 | MENU=11 | ITEM=38 | RQUERY=1 | NAME=Invoice Pembelian Per Kategori Barang | FILE=RI_sadita
SELECT ic.icnama , b.bkode , b.bnama , SUM(rid.jml) AS jml , SUM(rid.jml * rid.harga) AS subtotal , SUM(rid.jmldiskon) AS jmldiskon , SUM(rid.jmlpajak1) AS pajak1, rihargatermasukpajak , SUM(CASE rihargatermasukpajak WHEN 0 THEN ((rid.jml * rid.harga) - rid.jmldiskon) + rid.pajak1 WHEN 1 THEN ((rid.jml * rid.harga) - rid.jmldiskon) END) AS "total" FROM m4_ri ri JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_item b ON rid.idbarang = b.bid JOIN m1_item_category ic ON b.bkategori = ic.ickode WHERE ri.ristatus IN(2,3,4,7) GROUP BY b.bkategori ASC , rid.idbarang ASC ORDER BY b.bkategori ASC , rid.idbarang ASC;

-- RID=50000598 | MENU=11 | ITEM=39 | RQUERY=1 | NAME=KWITANSI | FILE=kwitansi1
SELECT ri.rinotransaksi AS sinotransaksi, k.knama AS sicustomer , ri.ritotaltransaksi AS sitotaltransaksi, ri.riuraian AS siuraian , ri.ricatatan AS sicatatan , f_nominal(ri.ritotaltransaksi , ri.rimatauang) AS terbilang FROM m4_ri ri JOIN m1_contact k ON ri.ribagianpembelian = k.kid ORDER BY ri.ritgl ASC , ri.riid ASC;

-- RID=50001651 | MENU=11 | ITEM=40 | RQUERY=1 | NAME=Transaksi RI | FILE=RI
SELECT riid, ricabang, rilokasi, rigudang, riasalbarangkategori, rijenispembelian, rijenispembeliankategori, risaldoawal, ricarabayar, risumber, riautonotransaksi, rinotransaksi, ritgl, rikodepa, risupplier, risupplierkontak, ri1alamat1, ri1alamat2, ri1alamat3, ri2alamat1, ri2alamat2, ri2alamat3, ribagianpembelian, ritermin, ritgljatuhtempo, riuraian, ricatatan, rinoref, ritglnoref, ritglpenutupan, rimatauang, rikurs, rihargatermasukpajak, ritotal, ridiskonpersen, rijmldiskon, ritotalpajak1detail, ritotalpajak2detail, ribiayalainpersen, ribiayalain, ritotaltransaksi, rijmlbayar, ristatuslunas, ritgllunas, rinofakturpajak, risdhbayarpajak, ritglbayarpajak, rirekdiskon, rirekpajak1, rirekpajak2, rirekbiayalain, rirekbayar, riidpr, riidcs, riidrq, riidbs, riidpo, riidipc, riidgrn, ristatusdnr, ristatusprt, ristatusrealisasi, ristatuspie, ritglpie, ristatusvpp, ristatus, ristatussebelumnya, rijmlrevisi, ricetakanke, riinputuser, riinputtgl, rimodifikasiuser, rimodifikasitgl, riposting, ripostingtgl, ritutupperiode, riisclose, rijmluangmuka, rirekuangmuka, riidap, idridetail, idri, idbarang, namabarang, tipebarang, jml, satuan, nilaisatuan, jmlbarang, satuanbarang, matauang, kurs, hargafix, harga, diskon, jmldiskon, pajak1, jmlpajak1, pajak2, jmlpajak2, cabang, lokasi, gudang, rekpersediaan, rekdiskonpembelian, rekhutangsementara, costcenter, divisi, subdivisi, proyek, catatan, urutan, idprdetail, idcsdetail, idrqdetail, idbsdetail, idpodetail, idipcdetail, idgrndetail, jmldnr, statusdnr, jmlprt, statusprt, jmlrealisasi, statusrealisasi, isclose FROM m4_ri ri JOIN m4_ri_detail rid ON ri.riid = rid.idri ORDER BY ri.ritgl ASC, ri.riid ASC, rid.idridetail ASC;

-- RID=50001759 | MENU=11 | ITEM=41 | RQUERY=1 | NAME=Laporan Pembelian Per Proyek  | FILE=pembelian per proyek
SELECT rid.proyek, p.pnama, ri.rinotransaksi, ri.ritgl, ri.risupplier, c.kkode, c.knama, ri.rihargatermasukpajak, (CASE ri.rihargatermasukpajak WHEN 1 THEN 'Include' ELSE 'Exclude' END) as rihargatermasukpajaknama, rid.idbarang, i.bkode, rid.namabarang, rid.jml, rid.satuan, rid.harga, rid.jmldiskon, rid.pajak1, rid.jmlpajak1, (CASE ri.rihargatermasukpajak WHEN 1 THEN (rid.jml * rid.harga) - rid.jmldiskon ELSE (rid.jml * rid.harga) - rid.jmldiskon + rid.jmlpajak1 END) as total , po.ponotransaksi , pod.jml as jmlpo , pod.satuan AS satuanpo, ri.ritgljatuhtempo FROM m4_ri ri JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_contact c ON ri.risupplier = c.kid JOIN m1_item i ON rid.idbarang = i.bid LEFT JOIN m1_project p ON rid.proyek = p.pkode LEFT JOIN m4_po_detail pod ON rid.idpodetail = pod.idpodetail LEFT JOIN m4_po po ON pod.idpo = po.poid WHERE ri.ristatus IN(2,3,4,7) ORDER BY rid.proyek, ri.ritgl, ri.rinotransaksi, rid.urutan;

-- RID=50001760 | MENU=11 | ITEM=42 | RQUERY=1 | NAME=Laporan Pembelian Per Proyek Per Barang | FILE=pembelian per proyek per produk
SELECT rid.proyek, p.pnama, ri.rinotransaksi, ri.ritgl, ri.risupplier, c.kkode, c.knama, ri.rihargatermasukpajak, (CASE ri.rihargatermasukpajak WHEN 1 THEN 'Include' ELSE 'Exclude' END) as rihargatermasukpajaknama, rid.idbarang, i.bkode, rid.namabarang, SUM(rid.jml) AS jml, rid.satuan, rid.harga, SUM(rid.jmldiskon) AS jmldiskon, rid.pajak1, SUM(rid.jmlpajak1) AS jmlpajak1, SUM(CASE ri.rihargatermasukpajak WHEN 1 THEN (rid.jml * rid.harga) - rid.jmldiskon ELSE (rid.jml * rid.harga) - rid.jmldiskon + rid.jmlpajak1 END) as total, ri.ritgljatuhtempo FROM m4_ri ri JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_contact c ON ri.risupplier = c.kid JOIN m1_item i ON rid.idbarang = i.bid LEFT JOIN m1_project p ON rid.proyek = p.pkode WHERE ri.ristatus IN(2,3,4,7) GROUP BY rid.proyek ASC, rid.idbarang ASC ORDER BY rid.proyek ASC, rid.idbarang ASC;

-- RID=50003788 | MENU=11 | ITEM=43 | RQUERY=1 | NAME=RI and PIB Reconciliation | FILE=RI PIB Summary
SELECT ri.ritgl , ri.rinotransaksi , ri.ritotaltransaksi , ri.rimatauang, ri.rikurs , ri.ritotaltransaksi * ri.rikurs AS dppamount , SUM(rid.jml) AS jml , ks.knama AS risupplier , ri.ritgljatuhtempo FROM m4_ri ri JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_item b ON rid.idbarang = b.bid JOIN m1_contact ks ON ri.risupplier = ks.kid WHERE b.bjenis = "P" GROUP BY ri.ritgl ASC , ri.rinotransaksi ASC ORDER BY ri.ritgl ASC , ri.rinotransaksi ASC;

-- RID=50003832 | MENU=11 | ITEM=44 | RQUERY=1 | NAME=Label QRCode | FILE=labelpci2
SELECT ri.ritgl, ri.rinotransaksi, i.bkode, i.bnama, rid.jml, n.angka FROM m4_ri ri JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_item i ON rid.idbarang = i.bid JOIN m0_number n ON n.angka <= rid.jml ORDER BY ri.ritgl, ri.rinotransaksi, rid.urutan, rid.idridetail, n.angka;

-- RID=50003841 | MENU=11 | ITEM=45 | RQUERY=1 | NAME=Daftar Invoice Pembelian (RI)  | FILE=pembelianpayment
SELECT ri.riid, ri.ritgl, ri.rinotransaksi, ri.ristatus, st.nama as ristatusnama, ri.risupplier, c.kkode as risupplierkode, c.knama as risuppliernama, ri.rigudang, w.wnama as rigudangnama, ri.rimatauang, ri.rikurs, ri.ritotaltransaksi, ri.ritermin, ri.ritgljatuhtempo FROM m4_ri ri JOIN m0_status st ON ri.ristatus = st.kode JOIN m1_contact c ON ri.risupplier = c.kid JOIN m1_warehouse w ON ri.rigudang = w.wkode ORDER BY ri.ritgl, ri.riinputtgl, ri.rinotransaksi, ri.riid;

-- RID=154 | MENU=12 | ITEM=1 | RQUERY=1 | NAME=Daftar Pengiriman Barang Retur (DNR) | FILE=ListDeliveryNoteReturn
