-- RID=303 | MENU=12 | ITEM=7 | RQUERY=1 | NAME=Pengiriman Barang Retur (DNR) | FILE=DeliveryNoteReturnDetailValas1
SELECT dnr.dnrtotaltransaksi , (dnr.dnrtotaltransaksi * dnr.dnrkurs) AS dnrtotaltransaksiRP , (dnr.dnrtotalpajak1detail + dnr.dnrtotalpajak2detail) AS pajak , (dnr.dnrtotalpajak1detail + dnr.dnrtotalpajak2detail) * dnr.dnrkurs AS pajakRP , dnr.dnrmatauang , ri.rinotransaksi , ks.knama AS dnrsupplier , dnr.dnrcatatan, dnr.dnrtgl , dnr.dnrnotransaksi , b.bkode , dnrd.tipebarang , dnrd.namabarang , dnrd.jml, dnrd.satuan , dnrd.matauang , dnrd.diskon , ((dnrd.jml * dnrd.harga) - dnrd.jmldiskon) AS total , dnrd.harga , ((dnrd.jml * (dnrd.harga * dnrd.kurs)) - dnrd.jmldiskon) AS totalRP , (dnrd.harga * dnrd.kurs) AS hargaRP FROM m4_dnr dnr JOIN m4_dnr_detail dnrd ON dnr.dnrid = dnrd.iddnr JOIN m1_item b ON dnrd.idbarang = b.bid LEFT JOIN m1_contact ks on dnr.dnrsupplier = ks.kid LEFT JOIN m4_ri_detail rid ON dnrd.idridetail = rid.idridetail LEFT JOIN m4_ri ri ON rid.idri = ri.riid GROUP BY dnr.dnrnotransaksi, b.bkode , dnrd.tipebarang , dnrd.namabarang , dnrd.satuan, dnrd.harga , dnrd.diskon ORDER BY dnr.dnrnotransaksi, dnrd.urutan;

