-- RID=461 | MENU=13 | ITEM=1 | RQUERY=1 | NAME=Daftar Retur Pembelian (PRT) | FILE=ListPurchaseReturn1
SELECT prt.prtnotransaksi, prt.prttgl, ksup.knama AS prtsupplier , prt.prtmatauang , prt.prtkurs , prdt.kurs, prt.prtdiskonpersen, prt.prtjmldiskon, prt.prtbiayalain, prt.prttotalpajak1detail , prdt.namabarang , ri.rinotransaksi , dnr.dnrnotransaksi, prdt.jml, prdt.satuan , prdt.diskon , prdt.harga , prt.prturaian, (prdt.jml * (prdt.harga * prdt.kurs) - prdt.jmldiskon * prdt.kurs) AS totalrp, ((prdt.jml * prdt.harga) - prdt.jmldiskon) AS totalvalas FROM m4_prt prt JOIN m4_prt_detail prdt ON prt.prtid = prdt.idprt JOIN m1_contact ksup ON prt.prtsupplier = ksup.kid LEFT JOIN m4_ri_detail rid ON prdt.idridetail = rid.idridetail LEFT JOIN m4_ri ri ON rid.idri = ri.riid LEFT JOIN m4_dnr_detail dnrd ON prdt.iddnrdetail = dnrd.iddnrdetail LEFT JOIN m4_dnr dnr ON dnrd.iddnr = dnr.dnrid ORDER BY prt.prttgl , prt.prtnotransaksi, prdt.urutan;

-- RID=156 | MENU=13 | ITEM=2 | RQUERY=1 | NAME=Daftar Retur Pembelian (PRT) | FILE=ListPurchaseReturn
SELECT prt.prtnotransaksi, prt.prttgl, ksup.knama AS prtsupplier , w.wnama AS prtgudang, st.nama AS prtstatus , prt.prtmatauang , prt.prtkurs , prt.prtdiskonpersen, prt.prtjmldiskon, prt.prtbiayalain, prt.prttotalpajak1detail , b.bkode , prdt.namabarang , ri.rinotransaksi , dnr.dnrnotransaksi, prdt.jml, prdt.satuan , prdt.diskon , prdt.harga , ((prdt.jml * prdt.harga) - prdt.jmldiskon) AS total FROM m4_prt prt JOIN m4_prt_detail prdt ON prt.prtid = prdt.idprt JOIN m1_item b ON prdt.idbarang = b.bid JOIN m1_contact ksup ON prt.prtsupplier = ksup.kid JOIN m1_warehouse w ON prt.prtgudang = w.wkode JOIN m0_status st ON prt.prtstatus = st.kode LEFT JOIN m4_ri_detail rid ON prdt.idridetail = rid.idridetail LEFT JOIN m4_ri ri ON rid.idri = ri.riid LEFT JOIN m4_dnr_detail dnrd ON prdt.iddnrdetail = dnrd.iddnrdetail LEFT JOIN m4_dnr dnr ON dnrd.iddnr = dnr.dnrid ORDER BY prt.prttgl , prt.prtnotransaksi, prdt.urutan;

-- RID=157 | MENU=13 | ITEM=3 | RQUERY=1 | NAME=Daftar Return Pembelian (PRT) Outstanding Pembayaran | FILE=ListPurchaseReturnOutstandingPayment
SELECT prt.prtnotransaksi, prt.prttgl, ksup.knama, prt.prturaian, prt.prtmatauang, prt.prtkurs, vp.vpnotransaksi, vp.vptgl, vp.vpcatatan, prdt.matauang, vppd.kurs, vppd.terbayar, vppd.jmlbayarvalas, vppd.jmlbayar FROM m4_prt prt JOIN m4_prt_detail prdt ON prt.prtid = prdt.idprt JOIN m1_contact ksup ON prt.prtsupplier = ksup.kid LEFT JOIN m4_vpp_detail vppd ON prdt.idprt = vppd.idtransaksi LEFT JOIN m4_vpp vpp ON vppd.idvpp = vpp.vppid LEFT JOIN m4_vp_detail vpd ON vppd.idvppdetail = vpd.idvppdetail LEFT JOIN m4_vp vp ON vpd.idvp = vp.vpid WHERE (vppd.sumber = 'PRT' AND vpp.vppstatusvp = 'S') GROUP BY prt.prtnotransaksi, vp.vpnotransaksi ORDER BY prt.prtnotransaksi, vp.vpnotransaksi, prdt.urutan;

-- RID=160 | MENU=13 | ITEM=4 | RQUERY=1 | NAME=Retur Pembelian (PRT) | FILE=PurchaseReturnDetail1_new
SELECT prthargatermasukpajak , CASE prthargatermasukpajak WHEN 0 THEN "Belum Termasuk Pajak" WHEN 1 THEN "Sudah Termasuk Pajak" END AS "caption" , f_nominal(prt.prttotaltransaksi, prt.prtmatauang) AS terbilang, ksup.knama , w.wnama AS prtgudang, prt.prturaian , prt.prttgl, prt.prtnotransaksi, prt.prtmatauang, prt.prtkurs, st.nama AS prtstatus, b.bkode, prdt.namabarang , ri.rinotransaksi , prdt.jml, prdt.satuan, prdt.diskon, prdt.harga, ((prdt.jml * prdt.harga) - prdt.jmldiskon) AS total, prt.prtjmldiskon, prt.prttotalpajak1detail, prt.prtbiayalain FROM m4_prt prt JOIN m4_prt_detail prdt ON prt.prtid = prdt.idprt JOIN m1_item b ON prdt.idbarang = b.bid JOIN m1_contact ksup ON prt.prtsupplier = ksup.kid JOIN m0_status st ON prt.prtstatus = st.kode JOIN m1_warehouse w ON prt.prtgudang = w.wkode LEFT JOIN m4_ri_detail rid ON prdt.idridetail = rid.idridetail LEFT JOIN m4_ri ri ON rid.idri = ri.riid /*LEFT JOIN m4_dnr_detail dnrd ON prdt.iddnrdetail = dnrd.iddnrdetail LEFT JOIN m4_dnr dnr ON dnrd.iddnr = dnr.dnrid */ ORDER BY prt.prttgl, prt.prtnotransaksi, prdt.urutan;

-- RID=513 | MENU=13 | ITEM=5 | RQUERY=1 | NAME=Retur Pembelian (PRT) | FILE=PurchaseReturnDetail1_new2
SELECT prthargatermasukpajak , CASE prthargatermasukpajak WHEN 0 THEN "Belum Termasuk Pajak" WHEN 1 THEN "Sudah Termasuk Pajak" END AS "caption" , f_nominal(prt.prttotaltransaksi, prt.prtmatauang) AS terbilang, ksup.knama , w.wnama AS prtgudang, prt.prturaian , prt.prttgl, prt.prtnotransaksi, prt.prtmatauang, prt.prtkurs, st.nama AS prtstatus, b.bkode, prdt.namabarang , ri.rinotransaksi , prdt.jml, prdt.satuan, prdt.diskon, prdt.harga, ((prdt.jml * prdt.harga) - prdt.jmldiskon) AS total, prt.prtjmldiskon, prt.prttotalpajak1detail, prt.prtbiayalain FROM m4_prt prt JOIN m4_prt_detail prdt ON prt.prtid = prdt.idprt JOIN m1_item b ON prdt.idbarang = b.bid JOIN m1_contact ksup ON prt.prtsupplier = ksup.kid JOIN m0_status st ON prt.prtstatus = st.kode JOIN m1_warehouse w ON prt.prtgudang = w.wkode LEFT JOIN m4_ri_detail rid ON prdt.idridetail = rid.idridetail LEFT JOIN m4_ri ri ON rid.idri = ri.riid /*LEFT JOIN m4_dnr_detail dnrd ON prdt.iddnrdetail = dnrd.iddnrdetail LEFT JOIN m4_dnr dnr ON dnrd.iddnr = dnr.dnrid */ ORDER BY prt.prttgl, prt.prtnotransaksi, prdt.urutan;

-- RID=483 | MENU=13 | ITEM=6 | RQUERY=1 | NAME=Retur Pembelian (PRT) Serial | FILE=PurchaseReturnDetail1_serial
