-- RID=163 | MENU=14 | ITEM=2 | RQUERY=1 | NAME=Rencana Pembayaran Hutang (VPP) | FILE=VendorPaymentPlan1
SELECT vpp.vppid , ks.knama AS vppsupplier , vpp.vppmatauang , vpp.vppkurs , vpp.vppuraian , vpp.vpptgl, vpp.vppnotransaksi , st.nama AS vppstatus, vppd.sumber, CASE vppd.sumber WHEN "RI" then ri.rinotransaksi WHEN "AP" THEN ap.apnotransaksi WHEN "PRT" then prt.prtnotransaksi WHEN "CA" THEN CONCAT(vppd.sumber,"(",coa.cnomor,")") END AS notransaksi, CASE vppd.sumber WHEN "RI" then ri.ritgl WHEN "AP" THEN ap.aptgl WHEN "PRT" then prt.prttgl END AS tgl, CASE vppd.sumber WHEN "RI" then ri.rimatauang WHEN "AP" THEN ap.apmatauang WHEN "PRT" then prt.prtmatauang WHEN "CA" THEN vppd.matauang END AS matauang, CASE vppd.sumber WHEN "RI" then ri.rikurs WHEN "AP" THEN ap.apkurs WHEN "PRT" then prt.prtkurs WHEN "CA" THEN vppd.kurs END AS kurs, CASE vppd.sumber WHEN "RI" then vppd.totaltransaksi WHEN "AP" THEN vppd.totaltransaksi WHEN "PRT" then vppd.totaltransaksi END AS totaltransaksi, CASE vppd.sumber WHEN "RI" then vppd.terbayar WHEN "AP" THEN vppd.terbayar WHEN "PRT" then vppd.terbayar END AS terbayar, CASE vppd.sumber WHEN "RI" then SUM(vppd.rencana) WHEN "AP" THEN SUM(vppd.rencana) WHEN "PRT" then SUM(vppd.rencana) END AS rencana, CASE vppd.sumber WHEN "RI" then vppd.jmlbayar WHEN "AP" THEN vppd.jmlbayar WHEN "PRT" then vppd.jmlbayar WHEN "CA" THEN vppd.jmlbayar END AS jmlbayar, CASE vppd.sumber WHEN "RI" then vppd.jmlbayarvalas WHEN "AP" THEN vppd.jmlbayarvalas WHEN "PRT" then vppd.jmlbayarvalas WHEN "CA" then vppd.jmlbayarvalas END AS jmlbayarvalas, CASE vppd.sumber WHEN "RI" then vppd.catatan WHEN "AP" THEN vppd.catatan WHEN "PRT" then vppd.catatan WHEN "CA" then coa.cnama END AS catatan FROM m4_vpp vpp JOIN m4_vpp_detail vppd ON vpp.vppid = vppd.idvpp JOIN m1_contact ks ON vpp.vppsupplier = ks.kid JOIN m0_status st ON vpp.vppstatus = st.kode LEFT JOIN m4_ri ri ON vppd.sumber = ri.risumber AND vppd.idtransaksi = ri.riid LEFT JOIN m4_ap ap ON vppd.sumber = ap.apsumber AND vppd.idtransaksi = ap.apid LEFT JOIN m4_prt prt ON vppd.sumber = prt.prtsumber AND vppd.idtransaksi = prt.prtid LEFT JOIN m1_coa coa ON vppd.rekhutangpiutang = coa.cnomor GROUP BY vpp.vpptgl, vpp.vppnotransaksi, vppd.idvppdetail ORDER BY vpp.vpptgl , vpp.vppid , vpp.vppnotransaksi , vppd.sumber = "RI" DESC , vppd.sumber = "AP" DESC , vppd.sumber = "PRT" DESC , vppd.sumber = "CA" DESC , vppd.urutan;

