-- RID=45462 | MENU=14 | ITEM=10 | RQUERY=1 | NAME=Pengajuan Pembayaran Hutang | FILE=VPP
SELECT (CASE vppd.sumber WHEN 'RI' THEN "RI" WHEN 'PRT' THEN "PRT" ELSE "CA" END) as summ, vpp.vppsupplier, c.kkode as vppsupplierkode, c.knama as vppsuppliernama, vpp.vppid, vpp.vppnotransaksi, vpp.vpptgl, vpp.vppstatus, st.nama as vppstatusnama, vppd.idvppdetail, vppd.sumber, vppd.idtransaksi, (CASE vppd.sumber WHEN 'RI' THEN IFNULL(ri.rinotransaksi,'') WHEN 'PRT' THEN IFNULL(prt.prtnotransaksi,'') ELSE CONCAT('CA','(',IFNULL(coa.cnama,''),')') END) as notransaksi, vppd.jmlbayar * 1 AS subt , (CASE vppd.sumber WHEN 'PRT' THEN vppd.jmlbayar * -1 ELSE vppd.jmlbayar END) * 1 as jmlbayar, (CASE vppd.sumber WHEN 'RI' THEN IFNULL(ri.ritgl,'1900-01-01') WHEN 'PRT' THEN IFNULL(prt.prttgl,'1900-01-01') ELSE IFNULL(vpp.vpptgl,'') END) as tgltransaksi, (CASE WHEN IFNULL(pie.piestatus,0) IN (2,3,4) THEN IFNULL(pie.pietgl,'1900-01-01') ELSE '1900-01-01' END) as tglpie, (CASE vppd.sumber WHEN 'RI' THEN IFNULL(ri.ritgljatuhtempo,'1900-01-01') WHEN 'PRT' THEN IFNULL(prt.prttgljatuhtempo,'1900-01-01') ELSE IFNULL(vpp.vpptgl,'') END) as tgljt FROM m4_vpp vpp JOIN m4_vpp_detail vppd ON vpp.vppid = vppd.idvpp JOIN m1_contact c ON vpp.vppsupplier = c.kid JOIN m0_status st ON vpp.vppstatus = st.kode JOIN m1_coa coa ON vppd.rekhutangpiutang = coa.cnomor LEFT JOIN m4_ri ri ON vppd.sumber = ri.risumber AND vppd.idtransaksi = ri.riid LEFT JOIN m4_prt prt ON vppd.sumber = prt.prtsumber AND vppd.idtransaksi = prt.prtid LEFT JOIN m4_pie_detail pied ON vppd.sumber = pied.sumber AND vppd.idtransaksi = pied.idtransaksi LEFT JOIN m4_pie pie ON pied.idpie = pie.pieid ORDER BY c.kkode, vpp.vpptgl, vpp.vppnotransaksi, vpp.vppid, vppd.urutan;

-- RID=50001661 | MENU=14 | ITEM=11 | RQUERY=1 | NAME=Transaksi VPP | FILE=VPP
SELECT vppid, vppcabang, vpplokasi, vppgudang, vppsumber, vppautonotransaksi, vppnotransaksi, vpptgl, vppkodepa, vppsupplier, vppsupplierkontak, vpp1alamat1, vpp1alamat2, vpp1alamat3, vpp2alamat1, vpp2alamat2, vpp2alamat3, vppbagianpembayaran, vppuraian, vppcatatan, vppnoref, vpptglnoref, vppcarabayar, vpptglbayar, vppmatauang, vppkurs, vpptotalap, vpptotalapvalas, vpptotalar, vpptotalarvalas, vppbayar, vppbayarvalas, vppselisihkurs, vpprekselisihkurs, vppdiskontermin, vppdiskonterminvalas, vpprekdiskontermin, vppstatusvp, vppstatus, vppstatussebelumnya, vppjmlrevisi, vppcetakanke, vppinputuser, vppinputtgl, vppmodifikasiuser, vppmodifikasitgl, vppposting, vpppostingtgl, vppisclose, idvppdetail, idvpp, sumber, idtransaksi, matauang, kurs, totaltransaksi, terbayar, rencana, sisa, jmlbayar, jmlbayarvalas, diskontermin, jmldiskontermin, jmldiskonterminvalas, rekhutangpiutang, catatan, costcenter, divisi, subdivisi, proyek, jmlvp, jmlvpvalas, statusvp, urutan, isclose FROM vpp vpp JOIN m4_vpp_detail vppd ON vpp.vppid = vppd.idvpp ORDER BY vpp.vpptgl ASC, vpp.vppid ASC, vppd.idvppdetail ASC;

-- RID=164 | MENU=15 | ITEM=1 | RQUERY=1 | NAME=Daftar Pembayaran Hutang (VP) 1 | FILE=ListVendorPayment
SELECT vp.vpnotransaksi, vp.vptgl, ks.knama AS vpsupplier, st.nama AS vpstatus , vp.vpuraian, vp.vpmatauang, vp.vpkurs, vp.vptotalap, vp.vptotalar, vp.vpbayar AS jumlahnayar FROM m4_vp vp JOIN m1_contact ks ON vp.vpsupplier = ks.kid JOIN m0_status st ON vp.vpstatus = st.kode ORDER BY vp.vptgl, vp.vpnotransaksi;

-- RID=433 | MENU=15 | ITEM=2 | RQUERY=1 | NAME=Daftar Pembayaran Hutang (VP) 2 | FILE=ListVendorPayment2
SELECT vp.vpnotransaksi, vp.vptgl, vppd.sumber, vppd.jmlbayar AS jmlbayar1, (CASE vppd.sumber WHEN "RI" THEN (vppd.jmlbayar) ELSE 0 END) AS totalRI, (CASE vppd.sumber WHEN "AP" THEN (vppd.jmlbayar) ELSE 0 END) AS totalAP, (CASE vppd.sumber WHEN "PRT" THEN (vppd.jmlbayar) ELSE 0 END) AS totalPRT, (CASE vppd.sumber WHEN "CA" THEN (vppd.jmlbayar) ELSE 0 END) AS totalCA, CASE vppd.sumber WHEN "RI" THEN (SELECT ri.rijmldiskon FROM m4_ri ri WHERE vppd.sumber = ri.risumber AND vppd.idtransaksi = ri.riid) WHEN "PRT" THEN (SELECT prt.prtjmldiskon FROM m4_prt prt WHERE vppd.sumber = prt.prtsumber AND vppd.idtransaksi = prt.prtid) ELSE 0 END AS jmldiskon, (vpp.vpptotalap - vpp.vpptotalar - vpp.vppselisihkurs) AS jmlbayar, vpp.vpptotalap , vpp.vpptotalar , vpp.vppselisihkurs, ks.kkategorisalesman, ks.knama FROM m4_vp vp JOIN m4_vp_detail vpd ON vp.vpid = vpd.idvp join m1_contact ks on vp.vpsupplier = ks.kid LEFT JOIN m4_vpp_detail vppd ON vppd.idvppdetail = vpd.idvppdetail LEFT JOIN m4_vpp vpp ON vpp.vppid = vppd.idvpp ORDER BY vp.vptgl , vp.vpnotransaksi;

-- RID=469 | MENU=15 | ITEM=3 | RQUERY=1 | NAME=Pembayaran Hutang (VP) | FILE=VendorPayment_new
SELECT ks.kkode , ks.knama AS vpsupplier , vp.vpmatauang , vp.vpkurs , vp.vpuraian , vp.vptgl, vp.vpnotransaksi , coa.cnomor, coa.cnama, st.nama AS vpstatus, vpd.sumber, CASE vpd.sumber WHEN "RI" then ri.rinotransaksi WHEN "AP" THEN ap.apnotransaksi WHEN "PRT" then prt.prtnotransaksi WHEN "CA" THEN CONCAT(vpd.sumber,"(",coa.cnomor,")") END AS notransaksi, CASE vpd.sumber WHEN "RI" then ri.ritgl WHEN "AP" THEN ap.aptgl WHEN "PRT" then prt.prttgl END AS tgl, CASE vpd.sumber WHEN "RI" then ri.rimatauang WHEN "AP" THEN ap.apmatauang WHEN "PRT" then prt.prtmatauang WHEN "CA" THEN vpd.matauang END AS matauang, CASE vpd.sumber WHEN "RI" then ri.rikurs WHEN "AP" THEN ap.apkurs WHEN "PRT" then prt.prtkurs WHEN "CA" THEN vpd.kurs END AS kurs, CASE vpd.sumber WHEN "RI" then vpd.totaltransaksi WHEN "AP" THEN vpd.totaltransaksi WHEN "PRT" then vpd.totaltransaksi END AS totaltransaksi, CASE vpd.sumber WHEN "RI" then vpd.terbayar WHEN "AP" THEN vpd.terbayar WHEN "PRT" then vpd.terbayar END AS terbayar, CASE vpd.sumber WHEN "RI" then SUM(vpd.rencana) WHEN "AP" THEN SUM(vpd.rencana) WHEN "PRT" then SUM(vpd.rencana) END AS rencana, CASE vpd.sumber WHEN "RI" then vpd.jmlbayar WHEN "AP" THEN (vpd.jmlbayar * -1) WHEN "PRT" then (vpd.jmlbayar * -1) WHEN "CA" THEN vpd.jmlbayar END AS jmlbayar, CASE vpd.sumber WHEN "RI" then vpd.jmlbayarvalas WHEN "AP" THEN (vpd.jmlbayarvalas * -1) WHEN "PRT" then (vpd.jmlbayarvalas * -1) WHEN "CA" then vpd.jmlbayarvalas END AS jmlbayarvalas, CASE vpd.sumber WHEN "RI" then vpd.catatan WHEN "AP" THEN vpd.catatan WHEN "PRT" then vpd.catatan WHEN "CA" then coa.cnama END AS catatan /*AP = RI , CA, AR(-) = AP, PRT */ FROM m4_vp vp JOIN m4_vp_detail vpd ON vp.vpid = vpd.idvp JOIN m1_contact ks ON vp.vpsupplier = ks.kid JOIN m0_status st ON vp.vpstatus = st.kode LEFT JOIN m4_ri ri ON vpd.sumber = ri.risumber AND vpd.idtransaksi = ri.riid LEFT JOIN m4_ap ap ON vpd.sumber = ap.apsumber AND vpd.idtransaksi = ap.apid LEFT JOIN m4_prt prt ON vpd.sumber = prt.prtsumber