-- RID=588 | MENU=50 | ITEM=1 | RQUERY=1 | NAME=Pembelian Per Supplier | FILE=pembelianpersupplier
SELECT ri.risupplier AS grup , ri.rinotransaksi, ri.ritgl, ks.knama AS risupplier , statuss.nama AS ristatus , ri.rimatauang , ri.rikurs , ri.ridiskonpersen , ri.rijmldiskon, ri.ribiayalain, (ri.ritotalpajak1detail + ri.ritotalpajak2detail) as ritotalpajak1detail, b.bkode , rid.namabarang , rid.jml, rid.satuan , rid.diskon, rid.harga, ((rid.jml * rid.harga) - rid.jmldiskon) AS total , kkategorisupplier , w.wnama AS gudanggrn FROM m4_ri ri JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_item b ON rid.idbarang = b.bid JOIN m1_contact ks ON ri.risupplier = ks.kid JOIN m0_status statuss ON ri.ristatus = statuss.kode LEFT JOIN m1_supplier_category sc ON ks.kkategorisupplier = sc.sckode LEFT JOIN m4_grn_detail grnd ON rid.idgrndetail = grnd.idgrndetail LEFT JOIN m4_grn grn ON grnd.idgrn = grn.grnid LEFT JOIN m1_warehouse w ON CASE WHEN IFNULL(grnd.idgrndetail,0) = 0 THEN ri.rigudang = w.wkode ELSE grn.grngudang = w.wkode END WHERE (ri.ristatus = 2 OR ri.ristatus = 3 OR ri.ristatus = 4 OR ri.ristatus = 7 ) ORDER BY ks.knama, ri.risupplier, ri.ritgl , ri.rinotransaksi, rid.urutan;

