-- RID=590 | MENU=50 | ITEM=3 | RQUERY=1 | NAME=Pembelian Per Kategori Barang | FILE=pembelianperkategoribarang
SELECT b.bkategori AS grup , ri.rinotransaksi, ri.ritgl, ks.knama AS risupplier , statuss.nama AS ristatus , ri.rimatauang , ri.rikurs , ri.ridiskonpersen , ri.rijmldiskon, ri.ribiayalain, ri.ritotalpajak1detail, b.bkode , rid.namabarang , rid.jml, rid.satuan , rid.diskon, rid.harga, ((rid.jml * rid.harga) - rid.jmldiskon) AS total , kkategorisupplier , ic.icnama FROM m4_ri ri JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_item b ON rid.idbarang = b.bid JOIN m1_contact ks ON ri.risupplier = ks.kid JOIN m0_status statuss ON ri.ristatus = statuss.kode JOIN m1_item_category ic ON b.bkategori = ic.ickode LEFT JOIN m1_supplier_category sc ON ks.kkategorisupplier = sc.sckode WHERE (ri.ristatus = 2 OR ri.ristatus = 3 OR ri.ristatus = 4 OR ri.ristatus = 7 ) ORDER BY b.bkategori , ri.ritgl , ri.rinotransaksi, rid.urutan;

-- RID=50000532 | MENU=50 | ITEM=4 | RQUERY=1 | NAME=Pembelian Per Produk Per Kategori Barang | FILE=RI_sadita
SELECT ic.icnama , b.bkode , b.bnama , SUM(rid.jml) AS jml , SUM(rid.jml * rid.harga) AS subtotal , SUM(rid.jmldiskon) AS jmldiskon , SUM(rid.jmlpajak1) AS pajak1, rihargatermasukpajak , SUM(CASE rihargatermasukpajak WHEN 0 THEN ((rid.jml * rid.harga) - rid.jmldiskon) + rid.jmlpajak1 WHEN 1 THEN ((rid.jml * rid.harga) - rid.jmldiskon) END) AS "total" FROM m4_ri ri JOIN m4_ri_detail rid ON ri.riid = rid.idri JOIN m1_item b ON rid.idbarang = b.bid JOIN m1_item_category ic ON b.bkategori = ic.ickode WHERE ri.ristatus IN(2,3,4,7) GROUP BY b.bkategori ASC , rid.idbarang ASC ORDER BY b.bkategori ASC , rid.idbarang ASC;

