-- RID=45456 | MENU=56 | ITEM=1 | RQUERY=1 | NAME=Tukar Faktur (PIE) | FILE=piexchange
SELECT pie.pieid, pie.pienotransaksi, pie.pietgl, pie.pieuraian, pie.piecatatan, c.kkode as supplierkode, c.knama as supppliernama, c.k1alamat1 as alamat, c.k1alamat2 as alamat2, st.nama as piestatusnama, pied.sumber, pied.idtransaksi, (CASE pied.sumber WHEN 'RI' THEN ri.rinotransaksi WHEN 'PRT' THEN prt.prtnotransaksi ELSE '' END) as notransaksi, (CASE pied.sumber WHEN 'RI' THEN ri.ritgl WHEN 'PRT' THEN prt.prttgl ELSE '1900-01-01' END) as tgl, (CASE pied.sumber WHEN 'RI' THEN ri.rimatauang WHEN 'PRT' THEN prt.prtmatauang ELSE '' END) as matauang, (CASE pied.sumber WHEN 'RI' THEN ri.rikurs WHEN 'PRT' THEN prt.prtkurs ELSE '' END) as kurs, (CASE pied.sumber WHEN 'RI' THEN ri.ritotaltransaksi WHEN 'PRT' THEN prt.prttotaltransaksi * -1 ELSE '0' END) as totaltransaksi, (CASE pied.sumber WHEN 'RI' THEN ri.ritermin WHEN 'PRT' THEN prt.prttermin ELSE '' END) as termin, IFNULL(tr.trharijatuhtempo,0) as harijatuhtempo, (CASE pied.sumber WHEN 'RI' THEN ri.ritgljatuhtempo WHEN 'PRT' THEN prt.prttgljatuhtempo ELSE '1900-01-01' END) as tgljatuhtempo, catatan, urutan, isclose, customtext1, customtext2, customtext3, customdbl1, customdbl2, customdbl3, customdate1, customdate2, customdate3 FROM m4_pie pie JOIN m4_pie_detail pied ON pie.pieid = pied.idpie JOIN m0_status st ON pie.piestatus = st.kode LEFT JOIN m4_ri ri ON pied.sumber = ri.risumber AND pied.idtransaksi = ri.riid LEFT JOIN m4_prt prt ON pied.sumber = prt.prtsumber AND pied.idtransaksi = prt.prtid LEFT JOIN m1_contact c ON IFNULL(ri.risupplier,prt.prtsupplier) = c.kid LEFT JOIN m1_terms tr ON IFNULL(ri.ritermin,prt.prttermin) = tr.trkode ORDER BY pie.pietgl, pie.pieid, pie.pienotransaksi, pied.urutan;

-- RID=45457 | MENU=56 | ITEM=2 | RQUERY=1 | NAME=Tukar Faktur (PIE) | FILE=piexchange2
SELECT pie.pieid, pie.pienotransaksi, pie.pietgl, pie.pieuraian, pie.piecatatan, c.kkode as supplierkode, c.knama as supppliernama, c.k1alamat1 as alamat, c.k1alamat2 as alamat2, st.nama as piestatusnama, pied.sumber, pied.idtransaksi, (CASE pied.sumber WHEN 'RI' THEN ri.rinotransaksi WHEN 'PRT' THEN prt.prtnotransaksi ELSE '' END) as notransaksi, (CASE pied.sumber WHEN 'RI' THEN ri.ritgl WHEN 'PRT' THEN prt.prttgl ELSE '1900-01-01' END) as tgl, (CASE pied.sumber WHEN 'RI' THEN ri.rimatauang WHEN 'PRT' THEN prt.prtmatauang ELSE '' END) as matauang, (CASE pied.sumber WHEN 'RI' THEN ri.rikurs WHEN 'PRT' THEN prt.prtkurs ELSE '' END) as kurs, (CASE pied.sumber WHEN 'RI' THEN ri.ritotaltransaksi WHEN 'PRT' THEN prt.prttotaltransaksi * -1 ELSE '0' END) as totaltransaksi, (CASE pied.sumber WHEN 'RI' THEN ri.ritermin WHEN 'PRT' THEN prt.prttermin ELSE '' END) as termin, IFNULL(tr.trharijatuhtempo,0) as harijatuhtempo, (CASE pied.sumber WHEN 'RI' THEN ri.ritgljatuhtempo WHEN 'PRT' THEN prt.prttgljatuhtempo ELSE '1900-01-01' END) as tgljatuhtempo, catatan, urutan, isclose, customtext1, customtext2, customtext3, customdbl1, customdbl2, customdbl3, customdate1, customdate2, customdate3 FROM m4_pie pie JOIN m4_pie_detail pied ON pie.pieid = pied.idpie JOIN m0_status st ON pie.piestatus = st.kode LEFT JOIN m4_ri ri ON pied.sumber = ri.risumber AND pied.idtransaksi = ri.riid LEFT JOIN m4_prt prt ON pied.sumber = prt.prtsumber AND pied.idtransaksi = prt.prtid LEFT JOIN m1_contact c ON IFNULL(ri.risupplier,prt.prtsupplier) = c.kid LEFT JOIN m1_terms tr ON IFNULL(ri.ritermin,prt.prttermin) = tr.trkode ORDER BY pie.pietgl, pie.pieid, pie.pienotransaksi, pied.urutan;

-- RID=50000591 | MENU=59 | ITEM=1 | RQUERY=1 | NAME=Undangan Penawaran | FILE=undangan_penawaran_detail
SELECT prd.idbarang , rfq.rfqid, rfq.rfqidpr, ks.kkode , ks.knama , pr.prmatauang , pr.prkurs , rfq.rfquraian , rfq.rfqtgl , rfq.rfqnotransaksi , st.nama , rfqd.idrfqdetail , b.bkode , b.bnama , prd.jml , prd.satuan , prd.harga , prd.diskon , (prd.jml * prd.harga) AS total , pr.prnotransaksi, pr.prjmldiskon , pr.prtotalpajak1detail , pr.prbiayalain , pr.prtotaltransaksi FROM m4_rfq rfq JOIN m0_status st on rfq.rfqstatus = st.kode JOIN m4_rfq_detail rfqd ON rfq.rfqid = rfqd.idrfq JOIN m1_contact ks ON rfqd.idkontak = ks.kid JOIN m4_pr pr on rfq.rfqidpr = pr.prid JOIN m4_pr_detail prd ON pr.prid = prd.idpr JOIN m1_item b ON prd.idbarang = b.bid ORDER BY rfq.rfqtgl ASC , rfq.rfqid ASC , rfqd.urutan ASC , prd.urutan;

