-- RID=50003780 | MENU=62 | ITEM=1 | RQUERY=1 | NAME=Purchase Contract Report | FILE=kontrak_beli
SELECT pfnotransaksi, k.kkode as supplierkode, k.knama AS suppliernama, ifnull (i.bdivisi,pfd.divisi) as divisi, ifnull(i.bnama,pfd.catatan) as catatan, pfd.jml - pfd.jmlrealisasi as jml, pfd.harga, pf.pfuraian, CASE IFNULL(bdivisi,divisi) WHEN "BR" THEN (jml - jmlrealisasi) * 1 ELSE 0 END AS totalbr, CASE IFNULL(bdivisi,divisi) WHEN "BW" THEN (jml - jmlrealisasi) * 1 ELSE 0 END AS totalbw, i.bkode, i.bnama FROM m4_pf pf JOIN m4_pf_detail pfd ON pf.pfid = pfd.idpf JOIN m1_contact k ON pf.pfsupplier = k.kid left join m1_item i on i.bid = pfd.idbarang WHERE (jml - jmlrealisasi )> 0 and pfstatus in(2,3) and customdbl2 = 0 ORDER BY pf.pftgl asc, k.knama asc;

-- RID=50003793 | MENU=62 | ITEM=2 | RQUERY=1 | NAME=Kontrak beli | FILE=KONTRAK BELI
SELECT pf.pfid, pf.pfnotransaksi , pf.pftgl , ks.knama AS pfsupplier , ic.ickode , ic.icnama , b.bkode , b.bnama , pfd.divisi , pfd.jml , pfd.satuan , pfd.harga FROM m4_pf pf JOIN m1_contact ks ON pf.pfsupplier = ks.kid JOIN m4_pf_detail pfd ON pf.pfid = pfd.idpf JOIN m1_item b ON pfd.idbarang = b.bid JOIN m1_item_category ic ON b.bkategori = ic.ickode ORDER BY pf.pftgl ASC , pf.pfnotransaksi ASC , ic.ickode ASC , pfd.urutan ASC;

